### 4. JavaScript — chattlogik
```javascript
const CHAT_ID = "main-" + Date.now(); // unik per session
let chatStreaming = false;

async function chatSend() {
    if (chatStreaming) return;
    const input = document.getElementById('chat-input');
    const message = input.value.trim();
    if (!message) return;

    input.value = '';
    chatStreaming = true;
    document.getElementById('chat-send-btn').disabled = true;
    document.getElementById('chat-diff-area').style.display = 'none';

    // Visa användarens meddelande
    appendChatMsg('user', message);

    // Skapa streaming-bubbla för assistenten
    const assistantBubble = appendChatMsg('assistant', '', true);
    let assistantText = '';

    try {
        const resp = await fetch('/api/chat', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({chat_id: CHAT_ID, message})
        });

        const reader = resp.body.getReader();
        const decoder = new TextDecoder();
        let buffer = '';

        while (true) {
            const {done, value} = await reader.read();
            if (done) break;
            buffer += decoder.decode(value, {stream: true});
            const lines = buffer.split('\n');
            buffer = lines.pop();

            for (const line of lines) {
                if (!line.startsWith('data: ')) continue;
                const event = JSON.parse(line.slice(6));

                if (event.type === 'text') {
                    assistantText += event.content;
                    assistantBubble.textContent = assistantText;
                    assistantBubble.scrollIntoView({block: 'end'});
                } else if (event.type === 'tool_start') {
                    appendToolCall(event.name, null, null);
                } else if (event.type === 'tool_result') {
                    updateLastToolCall(event.name, event.content);
                } else if (event.type === 'done') {
                    assistantBubble.classList.remove('streaming');
                    // Visa git diff om det finns
                    fetchAndShowDiff();
                }
            }
        }
    } catch (e) {
        assistantBubble.textContent = 'Fel: ' + e.message;
    }

    chatStreaming = false;
    document.getElementById('chat-send-btn').disabled = false;
}

function appendChatMsg(role, text, streaming = false) {
    const div = document.createElement('div');
    div.className = 'chat-msg ' + role + (streaming ? ' streaming' : '');
    div.textContent = text;
    document.getElementById('chat-messages').appendChild(div);
    div.scrollIntoView({block: 'end'});
    return div;
}

function appendToolCall(name, input, result) {
    const details = document.createElement('details');
    details.className = 'chat-tool-call';
    details.innerHTML = `<summary>🔧 ${name}</summary><pre>${result || '...'}</pre>`;
    details.dataset.toolName = name;
    document.getElementById('chat-messages').appendChild(details);
    return details;
}

function updateLastToolCall(name, result) {
    const calls = document.querySelectorAll('.chat-tool-call');
    for (let i = calls.length - 1; i >= 0; i--) {
        if (calls[i].dataset.toolName === name) {
            calls[i].querySelector('pre').textContent = result;
            break;
        }
    }
}

async function fetchAndShowDiff() {
    try {
        const resp = await fetch('/api/chat', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({chat_id: CHAT_ID, message: '__git_diff__'})
        });
        // Läs SSE tills done
        // ... (implementera som chatSend men extrahera bara text-events)
    } catch (e) {}
}

document.getElementById('chat-send-btn').addEventListener('click', chatSend);
document.getElementById('chat-input').addEventListener('keydown', e => {
    if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) chatSend();
});
document.getElementById('chat-clear-btn').addEventListener('click', async () => {
    await fetch('/api/chat/' + CHAT_ID, {method: 'DELETE'});
    document.getElementById('chat-messages').innerHTML = '';
});
```

### 5. Git diff-visning
Efter varje `done`-event: anropa `POST /api/chat` med `message: "__git_diff__"` (agenten kör git_status och returnerar diff). Visa resultatet i `#chat-diff-area`.

Alternativt enklare: lägg till en dedikerad `GET /api/chat/diff`-endpoint i backend som bara kör `git diff` och returnerar texten.

### 6. Godkänn-knappen
`#chat-approve-btn` anropar `/api/chat` med `message: "__commit_push__"` — agenten kör `git_commit_push` med ett auto-genererat commit-meddelande.

