### FIX 1 — UX-16: showToast stöder HTML (5 min)
Hitta showToast() i index.html. Ändra `textContent` → `innerHTML`:
```javascript
function showToast(msg, duration = 3000) {
  let t = document.getElementById('toast');
  if (!t) { t = document.createElement('div'); t.id = 'toast'; document.body.appendChild(t); }
  t.innerHTML = msg;  // ← ändrat från textContent
  t.className = 'toast show';
  clearTimeout(t._timer);
  t._timer = setTimeout(() => t.classList.remove('show'), duration);
}
```

### FIX 2 — UX-1: alert() → inline errors (6 ställen)
Lägg till showFieldError()-funktion FÖRE runReview():
```javascript
function showFieldError(fieldId, msg) {
  const el = document.getElementById(fieldId);
  if (!el) { showToast('⚠️ ' + msg, 4000); return; }
  el.style.outline = '2px solid var(--red, #ef4444)';
