(async function agentPulse() {
  const el = document.getElementById('agentPulse');
  if (!el) return;
  try {
    const r = await fetch('/api/agent-log');
    const { entries } = await r.json();
    if (!entries?.length) return;
    const last = entries[entries.length - 1];
    const names = { projektledare: '🗂', snickare: '🔨', granskare: '✅', specskrivare: '📝', logg: '📋' };
    const icon = names[last.agent] || '🤖';
    const note = last.note || (last.added?.length ? `+${last.added.length} task` : 'körde');
    el.textContent = `${icon} ${last.ts.slice(11,16)} — ${note}`;
    el.style.opacity = '0.7';
    // Blinka till vid ny post
    el.style.transition = 'none';
    el.style.opacity = '1';
    setTimeout(() => { el.style.transition = 'opacity 2s'; el.style.opacity = '0.5'; }, 2000);
  } catch {}
  setTimeout(agentPulse, 30_000);
})();
